You are the Assistant for BATCH-52 of the Elephant Rock Research Platform under AIV Framework v5.1.

Execute BOTH tasks. When done, write completion markers.

## TASK-01: Accessibility Testing with axe-core

### Step 1: Install jest-axe

```bash
cd frontend && npm install --save-dev jest-axe
```

### Step 2: Create `frontend/src/test/a11y-test-utils.ts`

```typescript
import { axe, toHaveNoViolations } from "jest-axe";
import { render } from "@testing-library/react";

expect.extend(toHaveNoViolations);

/**
 * Check a rendered component for WCAG 2.1 AA accessibility violations.
 * Usage: await checkA11y(<MyComponent />);
 */
export async function checkA11y(ui: React.ReactElement) {
  const { container } = render(ui);
  const results = await axe(container, {
    rules: {
      // Disable color-contrast in jsdom (no real CSS computed)
      "color-contrast": { enabled: false },
    },
  });
  expect(results).toHaveNoViolations();
}
```

Note: color-contrast must be disabled because jsdom doesn't compute real CSS styles.

### Step 3: Create `frontend/src/pages/__tests__/a11y.test.tsx`

Write a11y tests for key pages. You need to wrap each page in the necessary providers. Read existing page test files (like `dashboard.test.tsx` or `settings.test.tsx`) to understand how they wrap providers.

Test these 6 pages:
1. Dashboard
2. Ideas Browser
3. Gaps Explorer
4. Settings
5. Login
6. Knowledge Search

For each page, mock the API calls and render with providers, then run `checkA11y()`.

Use `vi.mock()` for API calls and wrap in MemoryRouter + any contexts needed.

### Step 4: Fix any violations

If any violations are found, fix them in the source files (add aria-labels, fix heading hierarchy, etc.)

---

## TASK-02: Error Monitoring Integration (Sentry)

### Backend Step 1: Install sentry-sdk

```bash
cd C:/Next-Era/elephant-rock-platform && pip install sentry-sdk
```

### Backend Step 2: Create `backend/monitoring/__init__.py`

```python
"""Error monitoring module (BATCH-52)."""
```

### Backend Step 3: Create `backend/monitoring/sentry.py`

```python
"""Sentry SDK integration for error monitoring (BATCH-52).

Initializes Sentry only when a DSN is configured.
When EROCK_SENTRY_DSN is empty (default), Sentry is completely disabled.
"""
import logging

logger = logging.getLogger(__name__)

_initialized = False


def init_sentry(dsn: str, environment: str = "production", traces_sample_rate: float = 0.1) -> bool:
    """Initialize Sentry SDK. Returns True if initialized, False if skipped."""
    global _initialized
    if not dsn:
        logger.info("Sentry DSN not configured — error monitoring disabled")
        return False

    try:
        import sentry_sdk
        from sentry_sdk.integrations.fastapi import FastApiIntegration

        sentry_sdk.init(
            dsn=dsn,
            environment=environment,
            integrations=[FastApiIntegration()],
            traces_sample_rate=traces_sample_rate,
        )
        _initialized = True
        logger.info("Sentry initialized (environment=%s)", environment)
        return True
    except ImportError:
        logger.warning("sentry-sdk not installed — error monitoring disabled")
        return False


def is_sentry_initialized() -> bool:
    return _initialized
```

### Backend Step 4: Add config to `backend/config.py`

Read the file first and add near the other observability settings:
```python
sentry_dsn: str = ""
sentry_environment: str = "production"
sentry_traces_sample_rate: float = 0.1
```

### Backend Step 5: Wire into `backend/api/app.py`

Add to the startup/lifespan section:
```python
from backend.monitoring.sentry import init_sentry
from backend.config import get_settings

settings = get_settings()
init_sentry(dsn=settings.sentry_dsn, environment=settings.sentry_environment, traces_sample_rate=settings.sentry_traces_sample_rate)
```

Look at how the app is configured — find the lifespan or startup event and add it there.

### Frontend Step 1: Install @sentry/react

```bash
cd frontend && npm install @sentry/react
```

### Frontend Step 2: Create `frontend/src/lib/sentry.ts`

```typescript
/**
 * Sentry React SDK initialization (BATCH-52).
 * Only initializes when VITE_SENTRY_DSN env var is set.
 */
export function initSentry(): boolean {
  const dsn = import.meta.env.VITE_SENTRY_DSN;
  if (!dsn) {
    return false;
  }

  try {
    const Sentry = require("@sentry/react");
    Sentry.init({
      dsn,
      tracesSampleRate: 0.1,
      environment: import.meta.env.MODE,
    });
    return true;
  } catch {
    return false;
  }
}
```

Actually, since this is TypeScript with Vite, use dynamic import or just regular import:

```typescript
import * as Sentry from "@sentry/react";

export function initSentry(): boolean {
  const dsn = import.meta.env.VITE_SENTRY_DSN;
  if (!dsn) {
    return false;
  }

  Sentry.init({
    dsn,
    tracesSampleRate: 0.1,
    environment: import.meta.env.MODE,
  });
  return true;
}

export { Sentry };
```

### Frontend Step 3: Update `frontend/src/main.tsx`

Read the file first, then add the Sentry init import and call before `root.render()`:

```typescript
import { initSentry } from "@/lib/sentry";
initSentry();
```

### Frontend Step 4: Update `frontend/src/components/error-boundary.tsx`

Read the file first to see the existing ErrorBoundary implementation. Add Sentry error capture:

```typescript
import * as Sentry from "@/lib/sentry";

// In componentDidCatch:
Sentry.Sentry.captureException(error);  // or Sentry.captureException if exported
```

### Tests

Create `backend/tests/test_api/test_batch52_task02.py` (+2 tests):
- Sentry init returns False when DSN is empty
- Sentry init returns False when sentry-sdk not importable (mock ImportError)

Create `frontend/src/lib/__tests__/sentry.test.ts` (+1 test):
- initSentry returns false when VITE_SENTRY_DSN is not set

