    // Rendering Settings without SettingsProvider should throw
    expect(() => {
      render(
        <MemoryRouter>
          <Settings />
        </MemoryRouter>,
      );
    }).toThrow("useSettings must be used within SettingsProvider");

    consoleSpy.mockRestore();
  });
});

