  const [searchText, setSearchText] = useState("");
  const [gapTypeFilter, setGapTypeFilter] = useState("");
  const [sortBy, setSortBy] = useState("confidence");
  const [minConfidence, setMinConfidence] = useState(0);
  const [page, setPage] = useState(0);
  const [activeTab, setActiveTab] = useState<"gaps" | "clusters">("gaps");
  const limit = 20;

  const queryParams = useMemo(
    () => ({
      search: searchText || undefined,
      gap_type: gapTypeFilter || undefined,
      sort_by: sortBy,
      sort_order: "desc",
      min_confidence: minConfidence > 0 ? minConfidence : undefined,
      limit,
      offset: page * limit,
    }),
    [searchText, gapTypeFilter, sortBy, minConfidence, page, limit],
  );

  const { data, isLoading } = useQuery({
    queryKey: ["gaps", queryParams],
    queryFn: () => listGaps(queryParams),
  });

  const { data: clusterData } = useQuery({
    queryKey: ["gap-clusters"],
    queryFn: () => apiFetch("/gaps/clusters") as Promise<{ clusters: any[]; total_papers: number }>,
    enabled: activeTab === "clusters",
  });

  const handleIdeaCountClick = (gap: ResearchGap) => {
    navigate(`/ideas?search=${encodeURIComponent(gap.title)}`);
  };

  const resetFilters = () => {
    setSearchText("");
    setGapTypeFilter("");
    setSortBy("confidence");
    setMinConfidence(0);
    setPage(0);
  };

  const hasActiveFilters =
    searchText !== "" || gapTypeFilter !== "" || sortBy !== "confidence" || minConfidence > 0;

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold tracking-tight">Research Gaps</h1>
          <p className="text-muted-foreground">
            Identified gaps in the literature, sorted by confidence.
          </p>
        </div>
        <div className="flex gap-1">
          <Button
            variant={activeTab === "gaps" ? "default" : "outline"}
            size="sm"
            onClick={() => setActiveTab("gaps")}
          >
            Gaps
          </Button>
          <Button
            variant={activeTab === "clusters" ? "default" : "outline"}
            size="sm"
            onClick={() => setActiveTab("clusters")}
          >
            Clusters
          </Button>
        </div>
      </div>

      {activeTab === "gaps" ? (
      <>
      <div className="flex flex-col gap-4 sm:flex-row sm:items-end">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
          <Input
            placeholder="Search gaps by title or description..."
            value={searchText}
            onChange={(e) => {
              setSearchText(e.target.value);
              setPage(0);
            }}
            className="pl-9"
            aria-label="Search gaps by title or description"
          />
        </div>

        <div className="flex items-end gap-4">
          <div className="w-[180px]">
            <label className="text-xs text-muted-foreground mb-1 block">Gap Type</label>
            <Select
              value={gapTypeFilter}
              onValueChange={(v) => {
                setGapTypeFilter(v);
                setPage(0);
              }}
            >
              <SelectTrigger aria-label="Filter by gap type">
                <SelectValue placeholder="All Types" />
              </SelectTrigger>
              <SelectContent>
                {GAP_TYPE_OPTIONS.map((opt) => (
                  <SelectItem key={opt.value} value={opt.value || "__all__"}>
                    {opt.label}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          <div className="w-[160px]">
            <label className="text-xs text-muted-foreground mb-1 block">
              Min Confidence: {minConfidence.toFixed(1)}
            </label>
            <Slider
              value={[minConfidence]}
              onValueChange={(v) => {
                setMinConfidence(v[0]);
                setPage(0);
              }}
              min={0}
              max={1}
              step={0.1}
              aria-label="Minimum confidence filter"
            />
          </div>

          <div className="w-[160px]">
            <label className="text-xs text-muted-foreground mb-1 block">Sort by</label>
            <Select
              value={sortBy}
              onValueChange={(v) => {
                setSortBy(v);
                setPage(0);
              }}
            >
              <SelectTrigger aria-label="Sort gaps by">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {SORT_OPTIONS.map((opt) => (
                  <SelectItem key={opt.value} value={opt.value}>
                    {opt.label}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          {hasActiveFilters && (
            <Button
              variant="ghost"
              size="sm"
              onClick={resetFilters}
              className="whitespace-nowrap"
            >
              Reset
            </Button>
          )}
        </div>
      </div>

      {isLoading ? (
        <div className="space-y-3">
          {Array.from({ length: 5 }).map((_, i) => (
            <Skeleton key={i} className="h-24 w-full" />
          ))}
        </div>
      ) : data?.gaps.length ? (
        <>
          <p className="text-sm text-muted-foreground">
            {data.total} gap{data.total !== 1 ? "s" : ""} found
          </p>
          <div className="space-y-3">
            {data.gaps.map((gap) => (
              <GapCard
                key={gap.id}
                gap={gap}
                onIdeaCountClick={handleIdeaCountClick}
              />
            ))}
          </div>
          {data.total > limit && (
            <div className="flex items-center justify-between pt-2">
              <Button
                variant="outline"
                size="sm"
                disabled={page === 0}
                onClick={() => setPage((p) => p - 1)}
              >
                <ChevronLeft className="mr-1 h-4 w-4" />
                Previous
              </Button>
              <span className="text-sm text-muted-foreground">
                Page {page + 1} of {Math.ceil(data.total / limit)}
              </span>
              <Button
                variant="outline"
                size="sm"
                disabled={(page + 1) * limit >= data.total}
                onClick={() => setPage((p) => p + 1)}
              >
                Next
                <ChevronRight className="ml-1 h-4 w-4" />
              </Button>
            </div>
          )}
        </>
      ) : (
        <div className="text-center py-12 text-muted-foreground">
          <GitBranch className="h-8 w-8 mx-auto mb-2 opacity-50" />
          <p>No research gaps found{searchText ? ` for "${searchText}"` : ""}.</p>
        </div>
      )}
      </>
      ) : (
        <div>
          {clusterData?.clusters?.length ? (
            <ClusterScatterPlot clusters={clusterData.clusters} />
          ) : (
            <p className="text-sm text-muted-foreground py-4">No cluster data available.</p>
          )}
          {clusterData && (
            <p className="text-sm text-muted-foreground mt-2">
              {clusterData.total_papers} papers across {clusterData.clusters.length} clusters
            </p>
          )}
        </div>
      )
      }
    </div>
  );
}

import { useState, useEffect, useCallback } from "react";
import { useSettings } from "@/contexts/settings-context";
import { useAuth } from "@/contexts/auth-context";
import { Input } from "@/components/ui/input";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { testConnection, getDetailedStatus, type DetailedStatus } from "@/api/client";
import { getEvolutionStatus, type EvolutionStatus } from "@/api/autonomous";
import { listUsers, type AuthUser } from "@/api/auth";
import { RoleBadge } from "@/components/auth/role-badge";

type ConnectionState = "idle" | "testing" | "connected" | "error";

export default function Settings() {
  const { apiUrl, apiKey, theme, setApiUrl, setApiKey, setTheme } = useSettings();

  // Connection test state
  const [connState, setConnState] = useState<ConnectionState>("idle");
  const [connError, setConnError] = useState<string>("");

  // Version / detailed status
  const [detailedStatus, setDetailedStatus] = useState<DetailedStatus | null>(null);

  // Evolution status (READ-ONLY per HB-01)
  const [evolutionStatus, setEvolutionStatus] = useState<EvolutionStatus | null>(null);

  // User management (admin only)
  const { user: currentUser } = useAuth();
  const [users, setUsers] = useState<AuthUser[]>([]);

  // Fetch users on mount if admin
  useEffect(() => {
    if (currentUser?.role === "admin") {
      listUsers()
        .then((data) => setUsers(data))
        .catch(() => {
          // Non-critical
        });
    }
  }, [currentUser?.role]);

  // Default domain
  const [defaultDomain, setDefaultDomain] = useState(() => {
    return localStorage.getItem("erock_default_domain") || "";
  });

  // Fetch version + evolution status on mount
  useEffect(() => {
    let cancelled = false;
    getDetailedStatus()
      .then((data) => {
        if (!cancelled) setDetailedStatus(data);
      })
      .catch(() => {
        // Version unavailable is non-fatal; just leave it null
      });
    getEvolutionStatus()
      .then((data) => {
        if (!cancelled) setEvolutionStatus(data);
      })
      .catch(() => {
        // Evolution unavailable is non-fatal
      });
    return () => {
      cancelled = true;
    };
  }, []);

  const handleTestConnection = useCallback(async () => {
    setConnState("testing");
    setConnError("");
    const result = await testConnection(apiUrl || undefined);
    if (result.ok) {
      setConnState("connected");
    } else {
      setConnState("error");
      setConnError(result.error);
    }
  }, [apiUrl]);

  const handleDefaultDomainChange = useCallback((value: string) => {
    setDefaultDomain(value);
    localStorage.setItem("erock_default_domain", value);
  }, []);

  /** Status dot color based on connection state. */
  const dotColor =
    connState === "connected"
      ? "bg-green-500"
      : connState === "error"
        ? "bg-red-500"
        : connState === "testing"
          ? "bg-yellow-500 animate-pulse"
          : "bg-gray-400";

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-2xl font-bold tracking-tight">Settings</h1>
        <p className="text-muted-foreground">Configure your API connection and preferences.</p>
      </div>

      {/* API Connection */}
      <Card>
        <CardHeader>
          <CardTitle className="text-lg">API Connection</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="space-y-2">
            <label className="text-sm font-medium">API Base URL</label>
            <Input
              placeholder="http://localhost:8000"
              value={apiUrl}
              onChange={(e) => setApiUrl(e.target.value)}
            />
            <p className="text-xs text-muted-foreground">
              Leave empty to use the Vite proxy (defaults to localhost:8000 in dev).
            </p>
          </div>

          <div className="space-y-2">
            <label className="text-sm font-medium">API Key</label>
            <Input
              type="password"
              placeholder="Optional API key"
              value={apiKey}
              onChange={(e) => setApiKey(e.target.value)}
            />
          </div>

          {/* Test Connection */}
          <div className="flex items-center gap-3">
            <Button
              onClick={handleTestConnection}
              disabled={connState === "testing"}
              variant="outline"
              data-testid="test-connection-btn"
            >
              {connState === "testing" ? "Testing..." : "Test Connection"}
            </Button>
            <span
              className={`inline-block h-3 w-3 rounded-full ${dotColor}`}
              data-testid="connection-dot"
              aria-label={
                connState === "connected"
                  ? "Connected"
                  : connState === "error"
                    ? "Connection error"
                    : "Not tested"
              }
            />
            {connState === "error" && (
              <span className="text-sm text-red-500" data-testid="connection-error">
                {connError}
              </span>
            )}
            {connState === "connected" && (
              <span className="text-sm text-green-600" data-testid="connection-success">
                Connected
              </span>
            )}
          </div>
        </CardContent>
      </Card>

      {/* Backend Info */}
      <Card>
        <CardHeader>
          <CardTitle className="text-lg">Backend Info</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="space-y-2 text-sm">
            <div className="flex items-center gap-2">
              <span className="font-medium">Version:</span>
              <span data-testid="backend-version">
                {detailedStatus?.version ?? "—"}
              </span>
            </div>
            <div className="flex items-center gap-2">
              <span className="font-medium">Provider:</span>
              <span data-testid="backend-provider">
                {detailedStatus?.provider ?? "—"}
              </span>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Default Domain */}
      <Card>
        <CardHeader>
          <CardTitle className="text-lg">Defaults</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="space-y-2">
            <label className="text-sm font-medium">Default Research Domain</label>
            <Input
              placeholder="e.g., AI/NLP, machine learning"
              value={defaultDomain}
              onChange={(e) => handleDefaultDomainChange(e.target.value)}
              data-testid="default-domain-input"
            />
            <p className="text-xs text-muted-foreground">
              Pre-fills the domain field in new pipeline runs. Saved in your browser.
            </p>
          </div>
        </CardContent>
      </Card>

      {/* Self-Improvement — READ-ONLY per HB-01 */}
      <Card data-testid="self-improve-section">
        <CardHeader>
          <CardTitle className="text-lg">Self-Improvement</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="space-y-2 text-sm">
            <div className="flex items-center gap-2">
              <span className="font-medium">Evolution:</span>
              <span data-testid="evolution-enabled-status">
                {evolutionStatus?.enabled ? "Enabled" : "Disabled"}
              </span>
            </div>
            <div className="flex items-center gap-2">
              <span className="font-medium">Overlays Generated:</span>
              <span data-testid="evolution-overlay-count">
                {evolutionStatus?.overlays_generated ?? "—"}
              </span>
            </div>
            <div className="flex items-center gap-2">
              <span className="font-medium">Recent Outcomes:</span>
              <span data-testid="evolution-outcome-count">
                {evolutionStatus?.recent_outcomes?.length ?? 0}
              </span>
            </div>
            {evolutionStatus?.recent_outcomes && evolutionStatus.recent_outcomes.length > 0 && (
              <div className="mt-2 space-y-1" data-testid="evolution-outcomes-list">
                {evolutionStatus.recent_outcomes.map((outcome, idx) => (
                  <div key={idx} className="flex items-center gap-2 text-xs text-muted-foreground">
                    <span className="font-mono">{outcome.stage_name}</span>
                    <span>score: {outcome.score.toFixed(2)}</span>
                    <span>({outcome.run_id})</span>
                  </div>
                ))}
              </div>
            )}
            <p className="text-xs text-muted-foreground mt-2">
              Evolution parameters are managed by the system and cannot be edited.
            </p>
          </div>
        </CardContent>
      </Card>

      {/* User Management (admin only) */}
      {currentUser?.role === "admin" && (
        <Card data-testid="user-management-section">
          <CardHeader>
            <CardTitle className="text-lg">User Management</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-3">
              {users.length === 0 ? (
                <p className="text-sm text-muted-foreground">No users found.</p>
              ) : (
                <div className="rounded-md border">
                  <table className="w-full text-sm">
                    <thead>
                      <tr className="border-b bg-muted/50">
                        <th className="px-3 py-2 text-left font-medium">Username</th>
                        <th className="px-3 py-2 text-left font-medium">Email</th>
                        <th className="px-3 py-2 text-left font-medium">Role</th>
                      </tr>
                    </thead>
                    <tbody>
                      {users.map((u) => (
                        <tr key={u.id} className="border-b last:border-0">
                          <td className="px-3 py-2">{u.username}</td>
                          <td className="px-3 py-2">{u.email}</td>
                          <td className="px-3 py-2">
                            <RoleBadge role={u.role} />
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )}
            </div>
          </CardContent>
        </Card>
      )}

      {/* Appearance */}
      <Card>
        <CardHeader>
          <CardTitle className="text-lg">Appearance</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="flex items-center gap-2">
            <Button
              variant={theme === "light" ? "default" : "outline"}
              onClick={() => setTheme("light")}
            >
              Light
            </Button>
            <Button
              variant={theme === "dark" ? "default" : "outline"}
              onClick={() => setTheme("dark")}
            >
              Dark
            </Button>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

/** Login / Register page (BATCH-28). */

import { useState, type FormEvent } from "react";
import { useNavigate } from "react-router-dom";
import { useAuth } from "@/contexts/auth-context";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";

export default function LoginPage() {
  const { login, register } = useAuth();
  const navigate = useNavigate();

  const [mode, setMode] = useState<"login" | "register">("login");
  const [username, setUsername] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [submitting, setSubmitting] = useState(false);

  async function handleSubmit(e: FormEvent) {
    e.preventDefault();
    setError("");
    setSubmitting(true);

    try {
      if (mode === "register") {
        await register(username, email, password);
      } else {
        await login(username, password);
      }
      navigate("/", { replace: true });
    } catch (err) {
      setError(
        err instanceof Error ? err.message : "Authentication failed",
      );
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <div className="flex items-center justify-center min-h-screen bg-background">
      <Card className="w-full max-w-sm">
        <CardHeader>
          <CardTitle className="text-xl text-center">
            {mode === "login" ? "Sign In" : "Create Account"}
          </CardTitle>
        </CardHeader>
        <CardContent>
          <form onSubmit={handleSubmit} className="space-y-4" data-testid="auth-form">
            <div className="space-y-2">
              <label className="text-sm font-medium" htmlFor="username">
                Username
              </label>
              <Input
                id="username"
                placeholder="Username"
                value={username}
                onChange={(e) => setUsername(e.target.value)}
                required
                data-testid="username-input"
              />
            </div>

            {mode === "register" && (
              <div className="space-y-2">
                <label className="text-sm font-medium" htmlFor="email">
                  Email
                </label>
                <Input
                  id="email"
                  type="email"
                  placeholder="you@example.com"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  required
                  data-testid="email-input"
                />
              </div>
            )}

            <div className="space-y-2">
              <label className="text-sm font-medium" htmlFor="password">
                Password
              </label>
              <Input
                id="password"
                type="password"
                placeholder="Password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                required
                data-testid="password-input"
              />
            </div>

            {error && (
              <p className="text-sm text-red-500" data-testid="auth-error">
                {error}
              </p>
            )}

            <Button
              type="submit"
              className="w-full"
              disabled={submitting}
              data-testid="auth-submit"
            >
              {submitting
                ? "Please wait..."
                : mode === "login"
                  ? "Sign In"
                  : "Create Account"}
            </Button>

            <div className="text-center text-sm">
              {mode === "login" ? (
                <span>
                  Don't have an account?{" "}
                  <button
                    type="button"
                    className="text-primary underline"
                    onClick={() => {
                      setMode("register");
                      setError("");
                    }}
                    data-testid="switch-to-register"
                  >
                    Register
                  </button>
                </span>
              ) : (
                <span>
                  Already have an account?{" "}
                  <button
                    type="button"
                    className="text-primary underline"
                    onClick={() => {
                      setMode("login");
                      setError("");
                    }}
                    data-testid="switch-to-login"
                  >
                    Sign In
                  </button>
                </span>
              )}
            </div>
          </form>
        </CardContent>
      </Card>
    </div>
  );
}

import { useState, useCallback } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { searchKnowledge, getKnowledgeStats } from "@/api/knowledge";
import { Input } from "@/components/ui/input";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { Search, Database, AlertCircle, FileText, Layers } from "lucide-react";
import { cn } from "@/lib/utils";
import { UploadZone } from "@/components/knowledge/upload-zone";

function distanceColor(distance: number): string {
  if (distance < 0.3) return "text-green-600";
  if (distance < 0.6) return "text-amber-600";
  return "text-red-600";
}

function distanceLabel(distance: number): string {
  if (distance < 0.3) return "High";
  if (distance < 0.6) return "Medium";
  return "Low";
}

export default function KnowledgeSearch() {
  const [query, setQuery] = useState("");
  const [submittedQuery, setSubmittedQuery] = useState<string | null>(null);
  const queryClient = useQueryClient();

  const { data, isLoading, isError } = useQuery({
    queryKey: ["knowledge-search", submittedQuery],
    queryFn: () => searchKnowledge(submittedQuery!),
    enabled: !!submittedQuery,
  });

  const { data: stats } = useQuery({
    queryKey: ["knowledge-stats"],
    queryFn: getKnowledgeStats,
  });

  const handleUploadSuccess = useCallback(() => {
    queryClient.invalidateQueries({ queryKey: ["knowledge-stats"] });
  }, [queryClient]);

  function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (!query.trim()) return;
    setSubmittedQuery(query.trim());
  }

  const results = data?.results ?? [];

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-2xl font-bold tracking-tight">Knowledge Base</h1>
        <p className="text-muted-foreground">Search the indexed literature and papers.</p>
      </div>

      {/* Stats Banner */}
      {stats && (
        <div data-testid="stats-banner" className="flex gap-4">
          <Card className="flex-1">
            <CardContent className="p-3 flex items-center gap-3">
              <FileText className="h-5 w-5 text-muted-foreground" />
              <div>
                <p className="text-xs text-muted-foreground">Documents</p>
                <p className="text-lg font-semibold" data-testid="stat-documents">{stats.total_documents}</p>
              </div>
            </CardContent>
          </Card>
          <Card className="flex-1">
            <CardContent className="p-3 flex items-center gap-3">
              <Layers className="h-5 w-5 text-muted-foreground" />
              <div>
                <p className="text-xs text-muted-foreground">Chunks</p>
                <p className="text-lg font-semibold" data-testid="stat-chunks">{stats.total_chunks}</p>
              </div>
            </CardContent>
          </Card>
        </div>
      )}

      <UploadZone onUploadSuccess={handleUploadSuccess} />

      <form onSubmit={handleSubmit} className="relative">
        <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
        <Input
          placeholder="Search papers, methods, findings..."
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          className="pl-9"
        />
      </form>

      {isLoading ? (
        <div className="space-y-3">
          {Array.from({ length: 3 }).map((_, i) => (
            <Skeleton key={i} className="h-24 w-full" />
          ))}
        </div>
      ) : isError ? (
        <div className="text-center py-12 text-destructive">
          <AlertCircle className="h-8 w-8 mx-auto mb-2 opacity-70" />
          <p>Search failed. Please try again.</p>
        </div>
      ) : submittedQuery && results.length === 0 ? (
        <div className="text-center py-12 text-muted-foreground">
          <Database className="h-8 w-8 mx-auto mb-2 opacity-50" />
          <p>No results found for "{submittedQuery}".</p>
        </div>
      ) : results.length > 0 ? (
        <div className="space-y-3">
          <p className="text-sm text-muted-foreground">
            {results.length} result{results.length !== 1 ? "s" : ""} for "{submittedQuery}"
          </p>
          {results.map((result) => (
            <Card key={result.id}>
              <CardContent className="p-4">
                <p className="text-sm whitespace-pre-wrap line-clamp-4">{result.text}</p>
                <div className="flex items-center flex-wrap gap-2 mt-3">
                  {result.metadata.source && (
                    <Badge variant="outline" className="text-xs">
                      {result.metadata.source}
                    </Badge>
                  )}
                  {result.metadata.year && (
                    <Badge variant="outline" className="text-xs">
                      {result.metadata.year}
                    </Badge>
                  )}
                  {result.metadata.authors && (
                    <span className="text-xs text-muted-foreground truncate max-w-[200px]">
                      {result.metadata.authors}
                    </span>
                  )}
                  <span className={cn("text-xs font-medium ml-auto", distanceColor(result.distance))}>
                    Relevance: {distanceLabel(result.distance)} ({result.distance.toFixed(3)})
                  </span>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      ) : null}
    </div>
  );
}

